From 30368a1ac333a103e7422df988d1e91c69b6576a Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 11:40:39 +0100
Subject: [PATCH] applets/systemtray: emit pressed instead of calling its
 handler

Forwarding a press to an applet called its MouseArea's onPressed handler
directly, since the pressed property hides the signal in QML, which made
Qt log a warning on clicks. Emit the signal from C++ instead.

BUG: 494438
---
 applets/systemtray/qml/PlasmoidItem.qml |  6 +-----
 applets/systemtray/systemtray.cpp       | 13 +++++++++++++
 applets/systemtray/systemtray.h         |  6 ++++++
 3 files changed, 20 insertions(+), 5 deletions(-)

diff --git a/applets/systemtray/qml/PlasmoidItem.qml b/applets/systemtray/qml/PlasmoidItem.qml
index bbefd007b5..e2fae3e858 100644
--- a/applets/systemtray/qml/PlasmoidItem.qml
+++ b/applets/systemtray/qml/PlasmoidItem.qml
@@ -60,11 +60,7 @@ AbstractItem {
             const appletItem = applet.compactRepresentationItem ?? applet.fullRepresentationItem
             const mouseArea = findMouseArea(appletItem)
             if (mouseArea) {
-                // The correct way here would be to invoke the "pressed"
-                // signal; however, mouseArea.pressed signal is overridden
-                // by its bool value, and our only option is to call the
-                // handler directly.
-                mouseArea.onPressed(mouse)
+                Plasmoid.emitPressed(mouseArea, mouse)
             }
         }
     }
diff --git a/applets/systemtray/systemtray.cpp b/applets/systemtray/systemtray.cpp
index 4c1db7a2e7..41d832c61c 100644
--- a/applets/systemtray/systemtray.cpp
+++ b/applets/systemtray/systemtray.cpp
@@ -501,6 +501,19 @@ void SystemTray::stackItemAfter(QQuickItem *newItem, QQuickItem *afterItem)
     newItem->stackAfter(afterItem);
 }

+void SystemTray::emitPressed(QQuickItem *mouseArea, QObject *mouseEvent)
+{
+    if (!mouseArea) {
+        return;
+    }
+    const QMetaObject *metaObject = mouseArea->metaObject();
+    const int index = metaObject->indexOfSignal("pressed(QQuickMouseEvent*)");
+    if (index < 0) {
+        return;
+    }
+    metaObject->method(index).invoke(mouseArea, Qt::DirectConnection, QGenericArgument("QQuickMouseEvent*", &mouseEvent));
+}
+
 void SystemTray::activate(const QString &service, QPoint pos, QQuickItem *statusNotifierIcon)
 {
     const auto source = StatusNotifierItemHost::self()->itemForService(service);
diff --git a/applets/systemtray/systemtray.h b/applets/systemtray/systemtray.h
index 8f06cfadf6..7dabdc4bd4 100644
--- a/applets/systemtray/systemtray.h
+++ b/applets/systemtray/systemtray.h
@@ -69,6 +69,12 @@ public:

     Q_INVOKABLE void stackItemAfter(QQuickItem *newItem, QQuickItem *afterItem);

+    /**
+     * Emits the pressed signal of a MouseArea, which QML can't reach because
+     * the pressed property shadows it
+     */
+    Q_INVOKABLE void emitPressed(QQuickItem *mouseArea, QObject *mouseEvent);
+
     Q_INVOKABLE void activate(const QString &service, QPoint pos, QQuickItem *statusNotifierIcon);

     Q_INVOKABLE void secondaryActivate(const QString &service, QPoint pos);
